style.css:
@-moz-document domain("gemini.google.com") {
/* 1. Increase the max-width while keeping the natural center alignment */
    .markdown-main-panel,
    [class*="message-content"], 
    [class*="conversation-container"],
    model-response-message-content {
        max-width: 1400px !important; 
    }

    /* Ensure the main panel adapts to the new maximum width */
    .markdown-main-panel {
        width: 100% !important; 
    }

    /* 2. Fix the table wrapper to prevent the fading/clipping effect */
    /* Removed the :has() pseudo-class to satisfy the linter */
    .markdown [class*="table"],
    .markdown [class*="table-wrapper"] {
        width: 100% !important;
        max-width: 100% !important;
        overflow-x: visible !important; 
    }

    /* 3. Force the table itself to expand to the full width of its new container */
    .markdown table {
        width: 100% !important;
        max-width: 100% !important;
        table-layout: auto !important; 
    }

    /* 4. Force text inside table cells to wrap normally */
    /* Swapped 'word-break: break-word' for standards-compliant properties */
    .markdown th,
    .markdown td {
        white-space: normal !important; 
        overflow-wrap: break-word !important;
        word-break: normal !important;
    }
}
